import random
import string
from typing import List, Tuple

# Generator for YAML text inputs that are valid and exercise different features.
# Focus: produce syntactically valid YAML covering scalars, sequences, mappings,
# anchors/aliases, tags, directives, multi-doc streams, different scalar styles,
# line breaks, Unicode, and indentation variants. Keep size <= 4096 bytes.

UNICODE_SAMPLES = [
    "café", "naïve", "東京", "😀", "ключ", "árbol", "Δοκιμή", "مرحبا",
]

PLAIN_SCALARS = [
    "true", "false", "null", "0", "42", "3.1415", "inf", "-inf", "nan",
    "2025-01-01", "12:34:56", "yes", "no", "on", "off",
]

DQ_ESCAPES = [
    "line\nbreak", "tab\tchar", "quote\"inside\"", "backslash\\",
]

LITERAL_BLOCKS = [
    "line1\nline2\nline3\n",
    "indented\n  two\n    three\n",
]

FOLDED_BLOCKS = [
    "fold this long line into multiple words that may wrap in output\nwith extra lines\n",
]

TAGS = [
    "!!str", "!!int", "!!bool", "!!seq", "!!map",
]

# Some safe YAML tag directive prefixes
TAG_DIRECTIVES: List[Tuple[str, str]] = [
    ("!e!", "tag:example.com,2025:"),
    ("!h!", "tag:home.test,2024:"),
]

def rnd(r: random.Random, seq):
    return r.choice(seq)

def gen_comment(r: random.Random) -> str:
    body = rnd(r, ["simple", "with # hash", "unicode " + rnd(r, UNICODE_SAMPLES)])
    return f"# {body}\n"

def gen_plain_scalar(r: random.Random) -> str:
    base = rnd(r, PLAIN_SCALARS + [rnd(r, UNICODE_SAMPLES), "plain words", "a:b", "1_000"])
    return base

def gen_single_quoted(r: random.Random) -> str:
    s = rnd(r, ["it""s", "O'Reilly", "single ' quote", "'' doubled ''"])  # YAML doubles single quotes
    # Escape by doubling quotes
    return "'" + s.replace("'", "''") + "'"

def gen_double_quoted(r: random.Random) -> str:
    s = rnd(r, DQ_ESCAPES + ["double \"quote\"", "unicode: \u263A", "mix " + rnd(r, UNICODE_SAMPLES)])
    return '"' + s + '"'

def gen_literal_block(r: random.Random, indent: int) -> str:
    chomp = rnd(r, ["", "-", "+"])  # chomp indicator
    content = rnd(r, LITERAL_BLOCKS)
    indent_str = " " * indent
    lines = content.splitlines(True)
    out = f"|{chomp}\n" + "".join(indent_str + l for l in lines)
    return out

def gen_folded_block(r: random.Random, indent: int) -> str:
    chomp = rnd(r, ["", "-", "+"])  # chomp indicator
    content = rnd(r, FOLDED_BLOCKS)
    indent_str = " " * indent
    lines = content.splitlines(True)
    out = f">{chomp}\n" + "".join(indent_str + l for l in lines)
    return out

def gen_scalar_any(r: random.Random, indent: int) -> str:
    choice = r.randrange(5)
    if choice == 0:
        return gen_plain_scalar(r)
    elif choice == 1:
        return gen_single_quoted(r)
    elif choice == 2:
        return gen_double_quoted(r)
    elif choice == 3:
        return gen_literal_block(r, indent)
    else:
        return gen_folded_block(r, indent)

def gen_seq_flow(r: random.Random, indent: int) -> str:
    n = r.randint(0, 6)
    items = [gen_scalar_any(r, indent) for _ in range(n)]
    return "[" + ", ".join(items) + "]"

def gen_seq_block(r: random.Random, indent: int) -> str:
    n = r.randint(1, 5)
    pad = " " * indent
    lines = []
    for _ in range(n):
        val = gen_scalar_any(r, indent + 2)
        if "\n" in val:  # block scalar
            lines.append(f"{pad}- {val}")
        else:
            lines.append(f"{pad}- {val}")
    return "\n".join(lines) + "\n"

def gen_map_flow(r: random.Random, indent: int) -> str:
    n = r.randint(0, 5)
    pairs = []
    for _ in range(n):
        k = gen_plain_scalar(r)
        v = gen_scalar_any(r, indent)
        pairs.append(f"{k}: {v}")
    return "{" + ", ".join(pairs) + "}"

def gen_map_block(r: random.Random, indent: int, allow_nested: bool = True) -> str:
    n = r.randint(1, 5)
    pad = " " * indent
    lines = []
    for i in range(n):
        key = gen_plain_scalar(r)
        # occasionally nest
        if allow_nested and r.random() < 0.35:
            nested = rnd(r, [gen_seq_block(r, indent + 2), gen_map_block(r, indent + 2, False)])
            lines.append(f"{pad}{key}:\n{nested}")
        else:
            val = gen_scalar_any(r, indent + 2)
            if "\n" in val:
                lines.append(f"{pad}{key}: {val}")
            else:
                lines.append(f"{pad}{key}: {val}")
    return "\n".join(lines) + "\n"

def gen_anchor_section(r: random.Random, indent: int) -> str:
    pad = " " * indent
    # Define an anchored mapping and reference it
    anchor_name = "a" + str(r.randint(1, 999))
    anchored = f"{pad}base: &{anchor_name}\n{pad}  x: 1\n{pad}  y: 2\n"
    alias_use = f"{pad}ref: *{anchor_name}\n"
    return anchored + alias_use

def gen_tag_directives(r: random.Random) -> str:
    # Optional %YAML and %TAG directives
    parts = []
    if r.random() < 0.6:
        vers = rnd(r, [(1,1), (1,2)])
        parts.append(f"%YAML {vers[0]}.{vers[1]}\n")
    if r.random() < 0.7:
        # 1-2 tag directives
        count = 1 if r.random() < 0.6 else 2
        for i in range(count):
            h, p = TAG_DIRECTIVES[i % len(TAG_DIRECTIVES)]
            parts.append(f"%TAG {h} {p}\n")
    return "".join(parts)

def gen_document(r: random.Random, indent: int, include_directives: bool, use_tags: bool, with_anchor: bool) -> str:
    parts = []
    if include_directives:
        parts.append(gen_tag_directives(r))
    # Optional explicit start
    if r.random() < 0.7:
        parts.append("---\n")
    # Top-level can be mapping or sequence or scalar
    choice = r.randrange(4)
    if choice == 0:
        # mapping with optional tags and anchors
        if with_anchor and r.random() < 0.7:
            parts.append(gen_anchor_section(r, indent))
        # add tagged entries
        if use_tags and r.random() < 0.6:
            t = rnd(r, TAGS)
            parts.append(f"root: {t} {gen_scalar_any(r, indent)}\n")
        parts.append(gen_map_block(r, indent))
    elif choice == 1:
        # sequence
        if r.random() < 0.5:
            parts.append("root: \n")
            parts.append(gen_seq_block(r, indent + 2))
        else:
            parts.append(gen_seq_block(r, indent))
    elif choice == 2:
        # flow structures
        parts.append("root_flow_seq: " + gen_seq_flow(r, indent) + "\n")
        parts.append("root_flow_map: " + gen_map_flow(r, indent) + "\n")
    else:
        # scalar at top
        parts.append(gen_scalar_any(r, indent))
        if not parts[-1].endswith("\n"):
            parts[-1] += "\n"
    # Optional explicit end
    if r.random() < 0.5:
        parts.append("...\n")
    return "".join(parts)

def maybe_comments(r: random.Random) -> str:
    s = ""
    for _ in range(r.randint(0, 2)):
        s += gen_comment(r)
    return s

def vary_line_breaks(r: random.Random, s: str) -> bytes:
    # Convert to specific line ending patterns to exercise YAML_BREAK preferences
    mode = r.randrange(3)
    if mode == 0:
        return s.replace("\n", "\r\n").encode("utf-8")  # CRLF
    elif mode == 1:
        return s.replace("\n", "\r").encode("utf-8")   # CR
    else:
        return s.encode("utf-8")  # LF


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Compose a multi-document stream (1-3 docs) with optional comments and directives.
    docs = []
    doc_count = 1 + r.randrange(3)

    # Global preamble comments
    stream = maybe_comments(r)

    for i in range(doc_count):
        include_directives = (i == 0 and r.random() < 0.9) or (r.random() < 0.2)
        use_tags = r.random() < 0.5
        with_anchor = r.random() < 0.7
        docs.append(gen_document(r, indent=r.randint(2, 4), include_directives=include_directives, use_tags=use_tags, with_anchor=with_anchor))
        # Inter-document comments
        stream += maybe_comments(r)
        stream += docs[-1]

    yaml_text = stream

    # Ensure non-empty (stub substitutes "a" otherwise)
    if not yaml_text.strip():
        yaml_text = "---\nkey: value\n"

    # Limit size to <= 4096 bytes by trimming extra comments/blocks if necessary.
    b = vary_line_breaks(r, yaml_text)
    if len(b) > 4096:
        # Truncate at a document boundary if possible
        cut = b.rfind(b"\n---", 0, 4096)
        if cut == -1:
            b = b[:4096]
        else:
            b = b[:cut]
        # Guarantee non-empty
        if not b:
            b = b"a"
    return b

import random
import secrets
import string
from typing import List

# Generator for YAML file data to be consumed by libyaml via yaml_parser_set_input_file.
# Goal: produce valid YAML documents with diverse constructs (scalars, sequences, mappings,
# anchors/aliases, tags, directives, multi-doc streams, different scalar styles, unicode, etc.).
# Keep outputs <= 4096 bytes.

ASCII_LETTERS = string.ascii_letters
DIGITS = string.digits
HEXDIG = '0123456789abcdef'
WS = ' \t'

# Some reusable scalars covering common YAML types and edge cases
PLAIN_SCALARS = [
    'null', 'true', 'false', '0', '1', '-1', '3.1415', '1e9',
    'yes', 'no', 'on', 'off', 'NaN', '.inf', '-.inf',
    'simple', 'with spaces', 'unquoted:colon', 'flow,comma',
    'bare#hash', 'unicode café', 'emoji 😀',
]

SINGLE_QUOTED = [
    "it's fine", "multi\nline\ntext", "quote: 'inside'", "escape\\backslash",
]

DOUBLE_QUOTED = [
    'line\nbreaks', 'tab\tsep', 'quote"inside"', 'unicode \u263A smile',
]

LITERALS = [
    'line1\nline2\n  indented\n',
    'trailing\n',
]

FOLDED = [
    'fold this long line into a single line with some words\nthat continue on the next line\n',
]

UNICODE_WORDS = ['東京', 'München', 'Киев', 'Κρήτη', 'Δοκιμή', '😀😺']

TAGS = [
    '!!str', '!!int', '!!bool', '!!seq', '!!map', '!custom', '!tag:example.com,2025:foo'
]

def rnd(r: random.Random, arr: List[str]):
    return r.choice(arr)

def gen_plain_word(r: random.Random) -> str:
    choices = [rnd(r, PLAIN_SCALARS)]
    # add randomized alnum tokens
    w = ''.join(r.choice(ASCII_LETTERS + DIGITS + '-_') for _ in range(r.randint(1, 12)))
    choices.append(w)
    if r.random() < 0.3:
        choices.append(rnd(r, UNICODE_WORDS))
    return rnd(r, choices)

def gen_single_quoted(r: random.Random) -> str:
    s = rnd(r, SINGLE_QUOTED)
    # duplicate single quotes to escape in YAML
    s = s.replace("'", "''")
    return "'" + s + "'"

def gen_double_quoted(r: random.Random) -> str:
    s = rnd(r, DOUBLE_QUOTED)
    return '"' + s + '"'

def gen_block_literal(r: random.Random) -> str:
    ind = ' ' * r.randint(2, 4)
    content = rnd(r, LITERALS)
    # indent each line
    lines = ''.join(ind + line if line else ind for line in content.splitlines(True))
    chomps = rnd(r, ['', '|', '|-', '|+'])
    return f"key_lit: {chomps}\n" + lines

def gen_block_folded(r: random.Random) -> str:
    ind = ' ' * r.randint(2, 4)
    content = rnd(r, FOLDED)
    lines = ''.join(ind + line if line else ind for line in content.splitlines(True))
    chomps = rnd(r, ['', '>', '>-', '>+'])
    return f"key_fold: {chomps}\n" + lines

def gen_anchor_alias_section(r: random.Random) -> str:
    # Define anchored mapping and reference it
    anchor = 'a' + ''.join(r.choice(ASCII_LETTERS + DIGITS) for _ in range(r.randint(3,6)))
    return (
        f"&{anchor} base: &{anchor} \n"  # anchor on a plain key-value scalar (permissible on nodes)
        f"ref1: *{anchor}\n"
    )

def gen_sequence(r: random.Random) -> str:
    n = r.randint(2, 6)
    items = []
    for _ in range(n):
        style = r.random()
        if style < 0.3:
            items.append('- ' + gen_plain_word(r))
        elif style < 0.6:
            items.append('- ' + gen_single_quoted(r))
        else:
            items.append('- ' + gen_double_quoted(r))
    return '\n'.join(items) + '\n'

def gen_flow_sequence(r: random.Random) -> str:
    n = r.randint(2, 6)
    elems = []
    for _ in range(n):
        choice = r.random()
        if choice < 0.33:
            elems.append(gen_plain_word(r))
        elif choice < 0.66:
            elems.append(gen_single_quoted(r))
        else:
            elems.append(gen_double_quoted(r))
    return '[' + ', '.join(elems) + ']'

def gen_mapping(r: random.Random) -> str:
    n = r.randint(2, 6)
    lines = []
    for _ in range(n):
        key = gen_plain_word(r)
        kind = r.random()
        if kind < 0.25:
            val = gen_plain_word(r)
        elif kind < 0.5:
            val = gen_flow_sequence(r)
        elif kind < 0.75:
            val = gen_double_quoted(r)
        else:
            val = gen_single_quoted(r)
        # occasionally add explicit tag
        if r.random() < 0.2:
            val = f"{rnd(r, TAGS)} {val}"
        lines.append(f"{key}: {val}")
    return '\n'.join(lines) + '\n'

def gen_directives(r: random.Random) -> str:
    parts = []
    if r.random() < 0.5:
        # Valid YAML versions commonly 1.1 or 1.2
        ver = rnd(r, [(1,1), (1,2)])
        parts.append(f"%YAML {ver[0]}.{ver[1]}")
    if r.random() < 0.4:
        # tag directives
        handle = '!h!'
        prefix = 'tag:example.com,2025:types/'
        parts.append(f"%TAG {handle} {prefix}")
    return ('\n'.join(parts) + ('\n' if parts else ''))

def gen_document(r: random.Random) -> str:
    # Optional directives + document markers
    s = []
    s.append(gen_directives(r))
    if r.random() < 0.6:
        s.append('---')
    # choose a top-level structure
    choice = r.random()
    if choice < 0.25:
        # simple scalar
        top = gen_plain_word(r)
        if r.random() < 0.3:
            top = f"{rnd(r, TAGS)} {top}"
        s.append(top)
    elif choice < 0.5:
        # block sequence
        s.append(gen_sequence(r))
    elif choice < 0.75:
        # mapping with some nested pieces
        body = gen_mapping(r)
        if r.random() < 0.5:
            # add nested sequence under a key
            body += 'list: \n' + ''.join('  ' + line for line in gen_sequence(r).splitlines(True))
        if r.random() < 0.5:
            # add nested mapping under a key
            nested = gen_mapping(r)
            body += 'nested: \n' + ''.join('  ' + line for line in nested.splitlines(True))
        s.append(body)
    else:
        # flow collection at top
        s.append(gen_flow_sequence(r))
    # Optional block scalars at end of document mapping context
    if r.random() < 0.5:
        s.append(gen_block_literal(r))
    if r.random() < 0.5:
        s.append(gen_block_folded(r))
    # anchors/aliases section (place in mapping context)
    if r.random() < 0.4:
        s.append(gen_anchor_alias_section(r))
    if r.random() < 0.4:
        s.append('...')
    return '\n'.join(part for part in s if part is not None and part != '') + '\n'

def gen_multi_document_stream(r: random.Random) -> str:
    docs = r.randint(1, 3)
    parts = []
    for i in range(docs):
        parts.append(gen_document(r))
    return ''.join(parts)

def sprinkle_comments(r: random.Random, text: str) -> str:
    if r.random() < 0.5:
        lines = text.splitlines()
        out = []
        for line in lines:
            out.append(line)
            if r.random() < 0.1:
                out.append('# ' + gen_plain_word(r))
        return '\n'.join(out) + '\n'
    return text

def maybe_trailing_newlines(r: random.Random, text: str) -> str:
    if r.random() < 0.5:
        return text + ('\n' * r.randint(1,3))
    return text

def add_random_unicode_spice(r: random.Random, text: str) -> str:
    if r.random() < 0.3:
        # Insert some unicode in comments to exercise emitter/parser unicode paths
        extra = '# ' + rnd(r, UNICODE_WORDS) + '\n'
        return extra + text
    return text

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Build a multi-document YAML stream with varied constructs
    yml = gen_multi_document_stream(r)
    yml = sprinkle_comments(r, yml)
    yml = add_random_unicode_spice(r, yml)
    yml = maybe_trailing_newlines(r, yml)
    # Ensure size constraint
    data = yml.encode('utf-8')
    if len(data) > 4096:
        data = data[:4096]
        # Ensure we end with a newline to keep YAML valid
        if not data.endswith(b'\n'):
            data = data[:-1] + b'\n'
    return data
